val Cream=Color(0xFFF7F2E9); val Ink=Color(0xFF211B18); val Coffee=Color(0xFF5A3C2D); val Line=Color(0xFFE7DED3)
data class Dish(val name:String,var price:Int,var cat:String,var enabled:Boolean=true,var imageUri:String?=null)
data class QrCfg(var bank:String="",var account:String="",var owner:String="",var prefix:String="0210",var enabled:Boolean=true,var printOnBill:Boolean=true)
data class Sale(val table:String,val total:Int,val method:String,val items:Map<String,Int>,val time:Long=System.currentTimeMillis())
fun money(v:Int)="%,dđ".format(v).replace(',','.')
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{Pos()}}}

@Composable fun Pos(){
 var screen by remember{mutableStateOf("TABLES")}; var table by remember{mutableStateOf("Bàn 01")}; val qr=remember{QrCfg()}
 val menu=remember{mutableStateListOf(Dish("Bún gà",40000,"Ăn sáng"),Dish("Bún gà đùi",55000,"Ăn sáng"),Dish("Cà phê đen",25000,"Cà phê"),Dish("Cà phê sữa",30000,"Cà phê"),Dish("Bạc xỉu",30000,"Cà phê"),Dish("Trà đào",35000,"Trà"),Dish("Sinh tố xoài",40000,"Sinh tố"))}
 val cart=remember{mutableStateMapOf<String,Int>()}; val sales=remember{mutableStateListOf<Sale>()}
 fun home(){screen="TABLES"}
 BackHandler(screen!="TABLES"){screen=when(screen){"ORDER"->"TABLES";"SENT"->"ORDER";"PAY"->"SENT";"MENU_ADD"->"MENU";else->"TABLES"}}
 MaterialTheme(colorScheme=lightColorScheme(primary=Coffee,background=Cream,surface=Color(0xFFFFFCF7),onSurface=Ink)){Surface(Modifier.fillMaxSize(),color=Cream){Box(Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.safeDrawing)){when(screen){
  "TABLES"->Tables({table=it;screen="ORDER"},{screen="MENU"},{screen="SETTINGS"},{screen="HISTORY"},{screen="REPORT"})
  "ORDER"->Order(table,menu,cart,{screen="TABLES"},::home,{screen="SENT"})
  "SENT"->Sent(table,cart,menu,{screen="ORDER"},{screen="PAY"},::home)
  "PAY"->Pay(table,qr,cart,menu,{screen="SENT"},{method,total->sales.add(Sale(table,total,method,cart.toMap()));cart.clear();home()},{screen="SETTINGS"})
  "MENU"->MenuManager(menu,::home,{screen="MENU_ADD"}); "MENU_ADD"->AddDish(menu){screen="MENU"}; "SETTINGS"->QrSettings(qr,::home)
  "HISTORY"->History(sales,::home); "REPORT"->Report(sales,menu,::home)
 }}}}
}
@Composable fun Header(title:String,sub:String="",back:(()->Unit)?=null,home:(()->Unit)?=null){Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){if(back==null)Column{Text("0210",fontSize=28.sp,fontWeight=FontWeight.Black);Text("Breakfast · Coffee · Drinks.",fontSize=10.sp)}else Text("‹",Modifier.clickable{back()}.padding(8.dp),fontSize=32.sp);Spacer(Modifier.weight(1f));Column(horizontalAlignment=Alignment.End){Text(title,fontSize=20.sp,fontWeight=FontWeight.Bold);if(sub.isNotBlank())Text(sub,fontSize=12.sp,color=Coffee)};if(home!=null)Text("⌂",Modifier.clickable{home()}.padding(8.dp),fontSize=24.sp)}}
@Composable fun Nav(active:String,history:()->Unit,report:()->Unit){Row(Modifier.fillMaxWidth().padding(horizontal=16.dp),horizontalArrangement=Arrangement.SpaceBetween){listOf("BÁN HÀNG","LỊCH SỬ","BÁO CÁO").forEach{x->val click=when(x){"LỊCH SỬ"->history;"BÁO CÁO"->report;else->{ { } }};Surface(color=if(x==active)Coffee else Color.Transparent,shape=RoundedCornerShape(8.dp),modifier=Modifier.clickable{click()}){Text(x,Modifier.padding(horizontal=14.dp,vertical=9.dp),color=if(x==active)Color.White else Ink,fontSize=12.sp,fontWeight=FontWeight.Bold)}}}}
@Composable fun Tables(open:(String)->Unit,menu:()->Unit,settings:()->Unit,history:()->Unit,report:()->Unit){Column{Header("","");Nav("BÁN HÀNG",history,report);Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text("Khu vực trong nhà",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("☰",Modifier.clickable{menu()}.padding(8.dp));Text("⚙",Modifier.clickable{settings()}.padding(8.dp))};LazyColumn(Modifier.weight(1f).padding(horizontal=16.dp)){items((1..10).chunked(2)){row->Row(Modifier.fillMaxWidth()){row.forEach{i->Card(Modifier.weight(1f).padding(5.dp).height(105.dp).clickable{open("Bàn %02d".format(i))},shape=RoundedCornerShape(12.dp)){Column(Modifier.fillMaxSize().padding(14.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("Bàn %02d".format(i),fontWeight=FontWeight.Bold);Text("Trống",fontSize=12.sp,color=Coffee)}}}}}};Row(Modifier.padding(16.dp)){OutlinedButton({},Modifier.weight(1f)){Text("＋ Bàn mới")};Spacer(Modifier.width(8.dp));Button({open("Mang đi")},Modifier.weight(1f)){Text("▣ MANG ĐI")}}}}
@Composable fun Order(t:String,menu:List<Dish>,cart:MutableMap<String,Int>,back:()->Unit,home:()->Unit,send:()->Unit){var cat by remember{mutableStateOf("Cà phê")};val cats=listOf("Cà phê","Ăn sáng","Trà","Sinh tố","Khác");val count=cart.values.sum();val total=menu.sumOf{it.price*(cart[it.name]?:0)};Column{Header(t,"ORDER MÓN",back,home);Row(Modifier.fillMaxWidth().padding(horizontal=10.dp),horizontalArrangement=Arrangement.SpaceEvenly){cats.forEach{x->Surface(color=if(cat==x)Coffee else Color(0xFFEDE6DC),shape=RoundedCornerShape(9.dp),modifier=Modifier.clickable{cat=x}){Text(x,Modifier.padding(10.dp),fontSize=12.sp,color=if(cat==x)Color.White else Ink)}}};LazyColumn(Modifier.weight(1f).padding(12.dp)){items(menu.filter{it.enabled&&it.cat==cat}){d->val q=cart[d.name]?:0;Card(Modifier.fillMaxWidth().padding(4.dp),shape=RoundedCornerShape(14.dp)){Row(Modifier.padding(10.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(74.dp).clip(RoundedCornerShape(10.dp)).background(Line),contentAlignment=Alignment.Center){if(d.imageUri!=null)AsyncImage(model=d.imageUri,contentDescription=d.name,modifier=Modifier.fillMaxSize(),contentScale=ContentScale.Crop)else Text("ẢNH",fontSize=11.sp)};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(d.name,fontWeight=FontWeight.Bold);Text(money(d.price),color=Coffee)};if(q==0)Button({cart[d.name]=1}){Text("+")}else Row(verticalAlignment=Alignment.CenterVertically){Text("−",Modifier.clickable{if(q<=1)cart.remove(d.name)else cart[d.name]=q-1}.padding(10.dp));Text("$q",fontWeight=FontWeight.Bold);Text("+",Modifier.clickable{cart[d.name]=q+1}.padding(10.dp))}}}}};Row(Modifier.padding(horizontal=18.dp),verticalAlignment=Alignment.CenterVertically){Text("▣  $count món",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text(money(total),fontWeight=FontWeight.Bold)};Row(Modifier.padding(16.dp)){OutlinedButton({},Modifier.weight(1f)){Text("XEM GIỎ HÀNG")};Spacer(Modifier.width(8.dp));Button(send,enabled=count>0,modifier=Modifier.weight(1f)){Text("GỬI LÀM HÀNG")}}}}
@Composable fun Sent(t:String,cart:Map<String,Int>,menu:List<Dish>,more:()->Unit,pay:()->Unit,home:()->Unit){Column{Header(t,"ĐÃ GỌI",more,home);Row(Modifier.padding(horizontal=16.dp)){Text("MENU",Modifier.weight(1f),textAlign=androidx.compose.ui.text.style.TextAlign.Center);Text("ĐÃ GỌI",Modifier.weight(1f),fontWeight=FontWeight.Bold,textAlign=androidx.compose.ui.text.style.TextAlign.Center)};Card(Modifier.fillMaxWidth().padding(16.dp)){Column(Modifier.padding(18.dp)){Row{Text("Đơn hiện tại",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("● Đã gửi bếp",color=Color(0xFF3F7D59))};cart.forEach{(n,q)->Text("$q  ×  $n",Modifier.padding(top=14.dp),fontWeight=FontWeight.Bold)}}};Spacer(Modifier.weight(1f));Row(Modifier.padding(16.dp)){OutlinedButton(more,Modifier.weight(1f)){Text("＋ GỌI THÊM")};Spacer(Modifier.width(8.dp));Button(pay,Modifier.weight(1f)){Text("▣ XEM TẠM TÍNH")}}}}
@Composable fun Pay(t:String,qr:QrCfg,cart:Map<String,Int>,menu:List<Dish>,back:()->Unit,done:(String,Int)->Unit,setup:()->Unit){var method by remember{mutableStateOf("CASH")};val total=menu.sumOf{it.price*(cart[it.name]?:0)};val configured=qr.bank.isNotBlank()&&qr.account.isNotBlank()&&qr.owner.isNotBlank();val info="${qr.prefix} ${t.replace("Bàn ","B")}";val bank=qr.bank.replace(" ","");val qrUrl="https://img.vietqr.io/image/${bank}-${qr.account}-compact2.png?amount=$total&addInfo=${URLEncoder.encode(info,StandardCharsets.UTF_8.toString())}&accountName=${URLEncoder.encode(qr.owner,StandardCharsets.UTF_8.toString())}";Column{Header("Thanh toán","",back,null);Column(Modifier.weight(1f).padding(18.dp)){Text(t,fontSize=22.sp,fontWeight=FontWeight.Bold);cart.forEach{(n,q)->val d=menu.firstOrNull{it.name==n};Row(Modifier.padding(vertical=8.dp)){Text("$q ×  $n");Spacer(Modifier.weight(1f));Text(money((d?.price?:0)*q))}};HorizontalDivider();Row(Modifier.padding(vertical=16.dp)){Text("Tổng cộng",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text(money(total),fontSize=24.sp,fontWeight=FontWeight.Black)};Text("Chọn phương thức thanh toán");Row(Modifier.padding(vertical=12.dp)){FilterChip(method=="CASH",{method="CASH"},{Text("▣  Tiền mặt")});Spacer(Modifier.width(10.dp));FilterChip(method=="TRANSFER",{method="TRANSFER"},{Text("▦  Chuyển khoản")})};if(method=="TRANSFER"){Card(Modifier.fillMaxWidth()){Column(Modifier.fillMaxWidth().padding(12.dp),horizontalAlignment=Alignment.CenterHorizontally){if(configured){AsyncImage(model=qrUrl,contentDescription="VietQR",modifier=Modifier.size(230.dp),contentScale=ContentScale.Fit);Text("${qr.bank} · ${qr.account}",fontWeight=FontWeight.Bold);Text(qr.owner);Text("Nội dung: $info",fontSize=12.sp)}else Button(setup){Text("CẤU HÌNH VIETQR")}}}}else{OutlinedTextField(total.toString(),{},readOnly=true,label={Text("Vừa nhận")},modifier=Modifier.fillMaxWidth());Row(Modifier.padding(top=8.dp)){listOf("150.000","200.000","500.000").forEach{x->AssistChip({}, {Text(x)});Spacer(Modifier.width(6.dp))}}}};Button({done(method,total)},Modifier.fillMaxWidth().padding(18.dp).height(58.dp)){Text("✓  XÁC NHẬN THANH TOÁN",fontWeight=FontWeight.Bold)}}}
@Composable fun History(sales:List<Sale>,back:()->Unit){Column{Header("Lịch sử","Giao dịch",back,back);if(sales.isEmpty())Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text("Chưa có giao dịch đã thanh toán",color=Coffee)}else LazyColumn(Modifier.padding(16.dp)){items(sales.reversed()){s->Card(Modifier.fillMaxWidth().padding(5.dp)){Row(Modifier.padding(16.dp)){Column{Text(s.table,fontWeight=FontWeight.Bold);Text(if(s.method=="CASH")"Tiền mặt" else "Chuyển khoản",fontSize=12.sp)};Spacer(Modifier.weight(1f));Text(money(s.total),fontWeight=FontWeight.Bold)}}}}}}
@Composable fun Report(sales:List<Sale>,menu:List<Dish>,back:()->Unit){val total=sales.sumOf{it.total};val cash=sales.filter{it.method=="CASH"}.sumOf{it.total};val transfer=total-cash;val counts=mutableMapOf<String,Int>();sales.forEach{s->s.items.forEach{(n,q)->counts[n]=(counts[n]?:0)+q}};Column{Header("Báo cáo","",back,back);Row(Modifier.padding(horizontal=16.dp)){listOf("Hôm nay","7 ngày","30 ngày","Tùy chọn").forEachIndexed{i,x->Surface(color=if(i==0)Coffee else Line,shape=RoundedCornerShape(8.dp)){Text(x,Modifier.padding(10.dp),fontSize=11.sp,color=if(i==0)Color.White else Ink)};Spacer(Modifier.width(5.dp))}};Card(Modifier.fillMaxWidth().padding(16.dp)){Column(Modifier.fillMaxWidth().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("Tổng doanh thu");Text(money(total),fontSize=32.sp,fontWeight=FontWeight.Black);Text("${sales.size} bill · TB ${money(if(sales.isEmpty())0 else total/sales.size)}",fontSize=12.sp)}};Row(Modifier.padding(horizontal=16.dp)){Card(Modifier.weight(1f)){Column(Modifier.padding(14.dp)){Text("Tiền mặt",fontSize=12.sp);Text(money(cash),fontWeight=FontWeight.Bold)}};Spacer(Modifier.width(8.dp));Card(Modifier.weight(1f)){Column(Modifier.padding(14.dp)){Text("Chuyển khoản",fontSize=12.sp);Text(money(transfer),fontWeight=FontWeight.Bold)}}};Text("Món bán chạy",Modifier.padding(18.dp),fontWeight=FontWeight.Bold);LazyColumn(Modifier.weight(1f).padding(horizontal=18.dp)){items(counts.entries.sortedByDescending{it.value}.take(5)){e->Row(Modifier.fillMaxWidth().padding(vertical=8.dp)){Text(e.key);Spacer(Modifier.weight(1f));Text("${e.value}",fontWeight=FontWeight.Bold)}}};Text("Doanh thu theo giờ",Modifier.padding(18.dp),fontWeight=FontWeight.Bold)}}
@Composable fun QrSettings(qr:QrCfg,back:()->Unit){var bank by remember{mutableStateOf(qr.bank)};var account by remember{mutableStateOf(qr.account)};var owner by remember{mutableStateOf(qr.owner)};var prefix by remember{mutableStateOf(qr.prefix)};Column{Header("Cài đặt","VietQR",back,back);Column(Modifier.padding(20.dp)){OutlinedTextField(bank,{bank=it},label={Text("Ngân hàng (VD: VietinBank)")},modifier=Modifier.fillMaxWidth());OutlinedTextField(account,{account=it.filter(Char::isDigit)},label={Text("Số tài khoản")},modifier=Modifier.fillMaxWidth());OutlinedTextField(owner,{owner=it.uppercase()},label={Text("Tên chủ tài khoản")},modifier=Modifier.fillMaxWidth());OutlinedTextField(prefix,{prefix=it.uppercase()},label={Text("Nội dung CK mặc định")},modifier=Modifier.fillMaxWidth());Button({qr.bank=bank.trim();qr.account=account.trim();qr.owner=owner.trim();qr.prefix=prefix.trim().ifBlank{"0210"};back()},Modifier.fillMaxWidth().padding(top=18.dp)){Text("LƯU CẤU HÌNH")}}}}
@Composable fun MenuManager(menu:MutableList<Dish>,back:()->Unit,add:()->Unit){Column{Header("Quản lý menu","V0.6",back,back);Button(add,Modifier.fillMaxWidth().padding(18.dp)){Text("＋ THÊM MÓN")};LazyColumn(Modifier.padding(14.dp)){items(menu){d->Card(Modifier.fillMaxWidth().padding(5.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(d.name,fontWeight=FontWeight.Bold);Text("${d.cat} · ${money(d.price)}")};Switch(d.enabled,{d.enabled=it;val i=menu.indexOf(d);menu[i]=d})}}}}}}
@Composable fun AddDish(menu:MutableList<Dish>,back:()->Unit){var name by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var cat by remember{mutableStateOf("Cà phê")};var image by remember{mutableStateOf<Uri?>(null)};var expanded by remember{mutableStateOf(false)};val picker=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){image=it};Column{Header("Thêm món","Menu",back,back);Column(Modifier.padding(20.dp)){OutlinedTextField(name,{name=it},label={Text("Tên món")},modifier=Modifier.fillMaxWidth());OutlinedTextField(price,{price=it.filter(Char::isDigit)},label={Text("Giá bán")},modifier=Modifier.fillMaxWidth());Box{OutlinedButton({expanded=true},Modifier.fillMaxWidth()){Text("PHÂN LOẠI: $cat")};DropdownMenu(expanded,{expanded=false}){listOf("Cà phê","Ăn sáng","Trà","Sinh tố","Khác").forEach{x->DropdownMenuItem({Text(x)},{cat=x;expanded=false})}}};OutlinedButton({picker.launch("image/*")},Modifier.fillMaxWidth()){Text(if(image==null)"CHỌN ẢNH ĐẠI DIỆN" else "✓ ĐÃ CHỌN ẢNH")};if(image!=null)AsyncImage(model=image,contentDescription=null,modifier=Modifier.fillMaxWidth().height(180.dp).clip(RoundedCornerShape(12.dp)),contentScale=ContentScale.Crop);Button({val p=price.toIntOrNull();if(name.isNotBlank()&&p!=null){menu.add(Dish(name,p,cat,true,image?.toString()));back()}},Modifier.fillMaxWidth().padding(top=18.dp)){Text("LƯU MÓN")}}}}
